<?php
namespace App\Http\Controllers;use App\Models\{Campus,FeedbackResponse};use App\Services\FeedbackCorrelationService;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\View\View;
class PublicFeedbackController extends Controller{public function create():View{return view('feedback.public',['campuses'=>Campus::with('buildings.floors.surveyAreas')->orderBy('name')->get()]);}public function store(Request $r,FeedbackCorrelationService $service):RedirectResponse{$d=$r->validate(['campus_id'=>'required|exists:campuses,id','building_id'=>'required|exists:buildings,id','floor_id'=>'required|exists:floors,id','survey_area_id'=>'nullable|exists:survey_areas,id','ssid'=>'nullable|string|max:100','problem_type'=>'required|in:weak_signal,slow_connection,cannot_connect,frequent_disconnection,buffering,high_latency,other','connection_stability'=>'required|in:stable,occasionally_unstable,frequently_unstable,disconnected','speed_satisfaction'=>'required|integer|between:1,5','overall_satisfaction'=>'required|integer|between:1,5','activity_type'=>'required|in:web_browsing,video_call,streaming,file_upload,learning_platform,other','buffering'=>'nullable|boolean','disconnection_count'=>'nullable|integer|between:0,1000','comment'=>'nullable|string|max:2000','experienced_at'=>'required|date|before_or_equal:now','consent'=>'accepted']);$feedback=FeedbackResponse::create($d+['public_id'=>(string)Str::uuid(),'submitted_at'=>now(),'source_ip_hash'=>hash('sha256',(string)$r->ip().config('app.key')),'user_agent_hash'=>hash('sha256',(string)$r->userAgent())]);$service->correlate($feedback);return redirect()->route('feedback.thank-you',['publicId'=>$feedback->public_id]);}public function thanks(string $publicId):View{$feedback=FeedbackResponse::where('public_id',$publicId)->firstOrFail();return view('feedback.thanks',compact('feedback'));}}
